d=json.loads(Path('benchmark/project-paired-0136.json').read_text())
r=d['rehearsal']
def inspect(x):
 errors=[]
 arms=x.get('arms',[])
 for c in r['checks']:
  op=c['op']; bad=False
  if op=='fields_complete': bad=set(x.get('fields',{}))!=set(d['fields']) or any(v.get('value') is None for v in x.get('fields',{}).values())
  elif op=='same': bad=len(arms)!=2 or any(arms[0].get(k) is None or arms[0].get(k)!=arms[1].get(k) for k in c['keys'])
  elif op=='plan': bad=not isinstance(x.get('repetitions'),int) or isinstance(x.get('repetitions'),bool) or x.get('repetitions',0)<1 or not x.get('stopping_rule')
  elif op=='model': bad=len(arms)!=2 or any(not a.get('actual_model') or a.get('actual_model')!=x.get('planned_model') for a in arms)
  elif op=='pair': bad=len(arms)!=2 or {a.get('arm') for a in arms}!={'no-tool','tool'} or any(a.get('execution_status')!='complete' or a.get('repetition')!=1 or a.get('pair_id')!=x.get('pair_id') for a in arms)
  elif op=='evidence':
   e=x.get(c['key']); bad=not isinstance(e,dict) or e.get('status')!='verified' or not e.get('identity')
  elif op=='raw': bad=len(arms)!=2 or any(not all(a.get('raw',{}).get(k) for k in r['raw_required']) for a in arms)
  if bad: errors.append(c['id'])
 return {'record_consistency':'reject' if errors else 'consistent','errors':errors,'real_admission':'blocked-synthetic' if x.get('synthetic') else 'blocked-pending-trusted-validation','semantic_assessment':None}
observed=[]
for case in r['cases']:
 x=copy.deepcopy(r['fixtures'][case['fixture']])
 for change in case['changes']:
  target=x
  for k in change['path'][:-1]: target=target[k]
  target[change['path'][-1]]=change['value']
 result=inspect(x)
 assert result==case['expected'], (case['id'],result,case['expected'])
 observed.append({'id':case['id'],'observed':result})
if 'observed' in r: assert observed==r['observed']
print(json.dumps({'cases':len(observed),'expected_equal_observed':True,'real_admissions':0,'semantic_passes':0,'observed':observed},indent=2))

